.communitysim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #233329;
    background: linear-gradient(160deg, #f1f6ec 0%, #e6f0e0 100%);
    border-radius: 18px;
}

.communitysim-container * {
    box-sizing: border-box;
}

.communitysim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #1f4d2e 0%, #2f7d4f 55%, #4fa06a 100%);
    color: #f3fbf4;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 10px 30px rgba(31, 77, 46, 0.30);
}

.communitysim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
}

.communitysim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #c8ecce;
    background: rgba(255, 255, 255, 0.13);
    padding: 5px 14px;
    border-radius: 999px;
}

.communitysim-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #e2f3e4;
}

.communitysim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #2c5238;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.communitysim-period-counter #currentDay,
.communitysim-period-counter #maxPeriods {
    font-weight: 800;
    color: #1f4d2e;
}

.communitysim-round-name {
    background: #d6ebd9;
    color: #1f4d2e;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.communitysim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #9a5b1d;
    background: #faecd9;
    padding: 4px 12px;
    border-radius: 999px;
}

.communitysim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.communitysim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #d4e6d6;
    box-shadow: 0 4px 14px rgba(31, 77, 46, 0.06);
    border-top: 4px solid #4fa06a;
}

.communitysim-card-sharing { border-top-color: #2f7d4f; }
.communitysim-card-engagement { border-top-color: #2f6fb0; }
.communitysim-card-innovation { border-top-color: #c98a16; }
.communitysim-card-recovered { border-top-color: #6a4fb0; }

.communitysim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #5e7765;
}

.communitysim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #1f4d2e;
}

.communitysim-card-sharing .communitysim-value { color: #2f7d4f; }
.communitysim-card-engagement .communitysim-value { color: #2f6fb0; }
.communitysim-card-innovation .communitysim-value { color: #b87d12; }
.communitysim-card-recovered .communitysim-value { color: #6a4fb0; }

.communitysim-sublabel {
    font-size: 0.76rem;
    color: #6f8a76;
    line-height: 1.35;
}

.communitysim-sharing-fail .communitysim-value { color: #c0392b; }
.communitysim-sharing-target .communitysim-value { color: #2f7d4f; }

.communitysim-resource-bar {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 14px;
    margin-bottom: 18px;
}

.communitysim-resource-block {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #1f4d2e;
    color: #eaf6ec;
    padding: 10px 18px;
    border-radius: 12px;
    font-weight: 700;
    font-size: 0.92rem;
}

.communitysim-resource-block.communitysim-resource-time {
    background: #2c5238;
}

.communitysim-resource-block #budgetDisplay,
.communitysim-resource-block #timeDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
}

.communitysim-resource-over {
    background: #8a2a1d !important;
}

.communitysim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #4fa06a;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(31, 77, 46, 0.05);
}

.communitysim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.communitysim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #1f4d2e;
    margin-bottom: 6px;
}

.communitysim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #354b3b;
}

.communitysim-briefing-text strong { color: #2f7d4f; }
.communitysim-briefing-text em { color: #9a5b1d; font-style: italic; }

.communitysim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #d4e6d6;
    box-shadow: 0 4px 14px rgba(31, 77, 46, 0.06);
}

.communitysim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #1f4d2e;
    border-bottom: 2px solid #e2efe2;
    padding-bottom: 8px;
}

.communitysim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #2c4633;
    margin: 14px 0 6px;
}

.communitysim-container select,
.communitysim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #bcd6bf;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #f6fbf4;
    color: #233329;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.communitysim-container select:focus,
.communitysim-container input[type="number"]:focus {
    outline: none;
    border-color: #2f7d4f;
    box-shadow: 0 0 0 3px rgba(47, 125, 79, 0.15);
}

.communitysim-container select option {
    background-color: #ffffff;
    color: #233329;
}

.communitysim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #2f7d4f;
}

.communitysim-range-readout,
.communitysim-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #2f7d4f;
    margin-top: 4px;
}

.communitysim-range-readout span:nth-child(2),
.communitysim-alloc-readout span:nth-child(2) {
    color: #1f4d2e;
    font-weight: 800;
}

.communitysim-hint {
    font-size: 0.8rem;
    color: #6f8a76;
    margin-top: 4px;
    line-height: 1.4;
}

.communitysim-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.communitysim-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #f2f8f1;
    border: 1px solid #dcecdd;
    border-radius: 9px;
    padding: 8px 12px;
}

.communitysim-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #2c4633;
}

.communitysim-alloc-row input[type="number"] {
    width: 100px;
    flex: 0 0 100px;
}

.communitysim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.communitysim-container .btn-primary {
    background: linear-gradient(135deg, #1f4d2e 0%, #2f7d4f 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 6px 16px rgba(31, 77, 46, 0.28);
}

.communitysim-container .btn-primary:hover {
    filter: brightness(1.08);
}

.communitysim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #bcd6bf;
    color: #5e7765;
}

.communitysim-coach {
    background: #1f4d2e;
    color: #eaf6ec;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(31, 77, 46, 0.22);
}

.communitysim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #8fd2a0;
    margin-bottom: 8px;
}

.communitysim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.communitysim-coach-body strong { color: #ffe09a; }
.communitysim-coach-body em { color: #ffc7a8; font-style: italic; }

.communitysim-history,
.communitysim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #d4e6d6;
    box-shadow: 0 4px 14px rgba(31, 77, 46, 0.06);
}

.communitysim-history h3,
.communitysim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #1f4d2e;
}

.communitysim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #2c4633;
}

.communitysim-container table#usfHistoryTable th {
    background: #e8f3e9;
    color: #1f4d2e;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #d2e6d4;
}

.communitysim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #eef5ef;
}

.communitysim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f7fbf7;
}

.communitysim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .communitysim-container {
        padding: 14px;
    }
    .communitysim-header h1 {
        font-size: 1.7rem;
    }
    .communitysim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .communitysim-value {
        font-size: 2rem;
    }
    .communitysim-clock {
        margin-left: 0;
    }
    .communitysim-period-counter {
        font-size: 0.88rem;
    }
    .communitysim-resource-bar {
        grid-template-columns: 1fr;
    }
    .communitysim-resource-block {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .communitysim-alloc-row {
        flex-wrap: wrap;
    }
    .communitysim-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .communitysim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ===== v1.1.0 completion modal (append-only, dark-on-light for the white modal) ===== */
.communitysim-completion { color:#233329; font-size:0.95rem; }
.communitysim-cm-head { text-align:center; margin-bottom:16px; }
.communitysim-cm-score { font-size:3.2rem; font-weight:800; line-height:1; color:#2f7d4f; }
.communitysim-cm-score-max { font-size:1.2rem; font-weight:600; color:#6aa17f; }
.communitysim-cm-grade { font-size:1.2rem; font-weight:700; margin-top:6px; color:#1f3326; }
.communitysim-cm-badge { display:inline-block; margin-left:6px; padding:2px 10px; border-radius:999px; font-size:0.78rem; font-weight:700; vertical-align:middle; }
.communitysim-cm-yes { background:rgba(47,125,79,0.14); color:#256b43; border:1px solid rgba(47,125,79,0.5); }
.communitysim-cm-no { background:rgba(201,138,22,0.16); color:#8a6a1f; border:1px solid rgba(201,138,22,0.5); }
.communitysim-cm-fail { background:rgba(192,57,43,0.12); color:#b0392b; border:1px solid rgba(192,57,43,0.45); }
.communitysim-cm-metrics { display:flex; flex-wrap:wrap; gap:10px; justify-content:center; margin:12px 0 16px; }
.communitysim-cm-metric { flex:1 1 110px; min-width:100px; background:rgba(31,77,46,0.06); border:1px solid rgba(31,77,46,0.16); border-radius:10px; padding:10px 8px; text-align:center; }
.communitysim-cm-mv { display:block; font-size:1.4rem; font-weight:800; color:#233d2b; }
.communitysim-cm-ml { display:block; font-size:0.72rem; margin-top:4px; color:#5e7765; text-transform:uppercase; letter-spacing:0.03em; }
.communitysim-cm-insights-title { font-weight:700; margin:8px 0 6px; color:#1f3326; }
.communitysim-cm-insights { margin:0; padding-left:20px; }
.communitysim-cm-insights li { margin:4px 0; color:#33473a; }

