(function() {
    'use strict';

    class CommunityAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Cultivating Communities`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card.
            this.START_SHARING = 9;      // mirrors the 9% failed-portal compliance floor
            this.START_ENGAGEMENT = 8;
            this.START_INNOVATION = 18;  // cross-sector idea flow; was 7/yr (≈ high), now 2 (low)
            this.TARGET_SHARING = 55;    // 12-month "demonstrable acceleration" target
            this.WASTE_TOTAL = 11;       // EUR 11M/year recoverable re-invention waste
            this.BUDGET_CAP = 1200;      // EUR 1.2M, in EUR thousands
            this.TIME_CAP = 5;           // 5% of engineers' time

            // Concept truths.
            this.TRUE_DOMAIN = `tacitcross`;
            this.TRUE_LENS = `match`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    sharing: this.START_SHARING,
                    engagement: this.START_ENGAGEMENT,
                    innovation: this.START_INNOVATION,
                    recovered: 0,
                    budgetUsed: 0,
                    timeUsed: 0,
                    overBudget: false,
                    repositoryReflex: false,
                    mandatedCommunities: false,
                    targetMissed: false,
                    sharingHistory: [this.START_SHARING],
                    engagementHistory: [this.START_ENGAGEMENT],
                    innovationHistory: [this.START_INNOVATION],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults are a MIDDLING / neutral mix — never the textbook-correct play.
                state.decisions = {
                    domain: `stableonly`,
                    lens: `allhierarchy`,
                    urgency: 50,
                    communities: 200,
                    rotation: 200,
                    directory: 200,
                    tools: 200,
                    repository: 200,
                    conference: 200,
                    leaders: `appoint`,
                    time: 3,
                    legitimacy: `mandatory`,
                    capture: `document`,
                    kpis: `annual`,
                    sustain: `relaunch`,
                    pitch: `vague`,
                    conviction: 60
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const dom = document.getElementById(`domainInput`);
                const lens = document.getElementById(`lensInput`);
                const urg = document.getElementById(`urgencyInput`);
                if (dom) decisions.domain = dom.value;
                if (lens) decisions.lens = lens.value;
                if (urg) decisions.urgency = parseInt(urg.value, 10);
                if (!Number.isFinite(decisions.urgency) || decisions.urgency < 0 || decisions.urgency > 100) {
                    warn(`warn_urgency_range`); return false;
                }
            } else if (round === 2) {
                const ids = [`communities`, `rotation`, `directory`, `tools`, `repository`, `conference`];
                let total = 0;
                let bad = false;
                ids.forEach((key) => {
                    const el = document.getElementById(key + `Input`);
                    if (el) {
                        const v = parseFloat(el.value);
                        decisions[key] = v;
                        if (!Number.isFinite(v) || v < 0) bad = true;
                        else total += v;
                    }
                });
                if (bad) { warn(`warn_alloc_negative`); return false; }
                if (Math.round(total) > this.BUDGET_CAP) { warn(`warn_alloc_over`); return false; }
            } else if (round === 3) {
                const ld = document.getElementById(`leadersInput`);
                const tm = document.getElementById(`timeInput`);
                const lg = document.getElementById(`legitimacyInput`);
                const cp = document.getElementById(`captureInput`);
                if (ld) decisions.leaders = ld.value;
                if (tm) decisions.time = parseFloat(tm.value);
                if (lg) decisions.legitimacy = lg.value;
                if (cp) decisions.capture = cp.value;
                if (!Number.isFinite(decisions.time) || decisions.time < 0 || decisions.time > 8) {
                    warn(`warn_time_range`); return false;
                }
            } else if (round === 4) {
                const kp = document.getElementById(`kpisInput`);
                const su = document.getElementById(`sustainInput`);
                const pt = document.getElementById(`pitchInput`);
                const cv = document.getElementById(`convictionInput`);
                if (kp) decisions.kpis = kp.value;
                if (su) decisions.sustain = su.value;
                if (pt) decisions.pitch = pt.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            // engagementDelta = genuine, voluntary community participation (the fuel for everything).
            // innovationDelta = cross-sector idea flow.
            // sharing is driven mostly by genuine engagement PLUS a small coerced/paper component
            // (mandate lifts the headline number but not real engagement, and decays sustainability).
            let engagementDelta = 0, innovationDelta = 0, paperDelta = 0;
            let spend = 0, time = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Map the flows — classify domains, match structure to knowledge (Common Errors 1 & 3).
                if (d.domain === this.TRUE_DOMAIN) {
                    engagementDelta += 10; innovationDelta += 6; coachKey = `coach_r1_domain_right`;
                } else if (d.domain === `everything`) {
                    engagementDelta += 1; innovationDelta += 1; paperDelta += 4; coachKey = `coach_r1_everything`;
                } else if (d.domain === `stableonly`) {
                    engagementDelta -= 5; innovationDelta -= 2; coachKey = `coach_r1_stableonly`;
                } else { // none -> rebuild the portal first
                    engagementDelta -= 8; innovationDelta -= 3; paperDelta += 3; coachKey = `coach_r1_none`;
                }

                if (d.lens === this.TRUE_LENS) {
                    engagementDelta += 8; innovationDelta += 5;
                    if (d.domain === this.TRUE_DOMAIN) coachKey = `coach_r1_map_sharp`;
                } else if (d.lens === `allcommunity`) {
                    engagementDelta += 1; paperDelta += 2; coachKey = (coachKey === `coach_r1_domain_right`) ? `coach_r1_allcommunity` : coachKey;
                } else { // allhierarchy
                    engagementDelta -= 6; innovationDelta -= 3; coachKey = `coach_r1_allhierarchy`;
                }

                // Urgency: prioritising the retiring architects' tacit knowledge early.
                if (d.urgency >= 60) { engagementDelta += 4; innovationDelta += 2; }
                else if (d.urgency <= 25) { engagementDelta -= 4; }

                summaryKey = (d.domain === this.TRUE_DOMAIN && d.lens === this.TRUE_LENS) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Allocate EUR 1.2M across structures (Common Errors 1 & 3).
                const com = d.communities, rot = d.rotation, dir = d.directory;
                const tol = d.tools, rep = d.repository, con = d.conference;
                spend = com + rot + dir + tol + rep + con;

                // Communities of practice — the central engine for tacit, cross-unit knowledge.
                if (com >= 350) { engagementDelta += 9; innovationDelta += 6; }
                else if (com >= 150) { engagementDelta += 5; innovationDelta += 3; }
                else { engagementDelta -= 5; coachKey = `coach_r2_nocommunities`; }

                // Rotation & shadowing — socialisation that genuinely moves tacit knowledge (SECI).
                if (rot >= 200) { engagementDelta += 5; innovationDelta += 3; }
                else if (rot >= 100) { engagementDelta += 3; innovationDelta += 2; }

                // Expert directory & light tools — useful enablers in moderation.
                if (dir > 0 && dir <= 250) engagementDelta += 3;
                else if (dir > 400) { engagementDelta += 1; }
                if (tol > 0 && tol <= 250) { engagementDelta += 3; innovationDelta += 2; }
                else if (tol > 400) { engagementDelta += 1; }

                // Codified repository / mandatory portal — the repository reflex (Common Error 1).
                // Over-investing here repeats the 9%-compliance failure: a headline bump, no belief.
                if (rep >= 500) {
                    engagementDelta -= 8; paperDelta += 6; ds.repositoryReflex = true; coachKey = `coach_r2_repository`;
                } else if (rep >= 300) {
                    engagementDelta -= 4; paperDelta += 3; coachKey = (coachKey === `coach_default`) ? `coach_r2_repoheavy` : coachKey;
                } else if (rep > 0 && rep <= 200) {
                    engagementDelta += 2; // a light, well-scoped repository for stable/compliance knowledge is fine
                }

                // Internal conference — a one-off event; energy without sustained dynamics.
                if (con >= 350) { engagementDelta -= 2; paperDelta += 2; coachKey = (coachKey === `coach_default`) ? `coach_r2_conference` : coachKey; }
                else if (con > 0 && con <= 200) { engagementDelta += 2; innovationDelta += 1; }

                // Balanced, community-weighted portfolio recognised explicitly.
                const communityWeighted = (com + rot) >= 550 && rep < 300;
                if (communityWeighted && coachKey === `coach_default`) coachKey = `coach_r2_balanced`;

                summaryKey = communityWeighted ? `sum_r2_good` : (ds.repositoryReflex ? `sum_r2_repo` : `sum_r2_weak`);
            } else if (round === 3) {
                // Cultivate engagement & legitimacy (Common Errors 2, 4 & 5).
                // Community leaders — cultivated and resourced vs unresourced vs appointed-managers.
                switch (d.leaders) {
                    case `resourced`: engagementDelta += 8; innovationDelta += 3; coachKey = `coach_r3_resourced`; break;
                    case `volunteer`: engagementDelta -= 4; coachKey = `coach_r3_volunteer`; break;
                    case `appoint`: engagementDelta -= 6; paperDelta += 4; coachKey = `coach_r3_appoint`; break;
                }

                // Protected billable time — the delivery-director injection (cut 5% -> 2%).
                time = d.time;
                if (d.time >= 5) { engagementDelta += 8; innovationDelta += 3; coachKey = `coach_r3_holdline`; }
                else if (d.time >= 3.5) { engagementDelta += 4; coachKey = (coachKey === `coach_r3_resourced`) ? coachKey : `coach_r3_partialtime`; }
                else if (d.time <= 2) { engagementDelta -= 9; paperDelta += 4; coachKey = `coach_r3_caved`; }
                else { engagementDelta -= 3; }

                // Legitimacy — sponsorship without over-formalising (Common Error 2).
                switch (d.legitimacy) {
                    case `sponsornoformal`: engagementDelta += 7; innovationDelta += 3; break;
                    case `mandatory`: engagementDelta -= 10; paperDelta += 6; ds.mandatedCommunities = true; coachKey = `coach_r3_mandated`; break;
                    case `none`: engagementDelta -= 5; coachKey = (coachKey === `coach_r3_resourced`) ? `coach_r3_nolegit` : coachKey; break;
                }

                // Retiring architects' tacit capture — socialisation, not documentation (Common Error linked).
                switch (d.capture) {
                    case `mentoring`: engagementDelta += 4; innovationDelta += 6; break;
                    case `document`: innovationDelta -= 4; coachKey = (coachKey === `coach_r3_resourced`) ? `coach_r3_documenttacit` : coachKey; break;
                    case `ignore`: engagementDelta -= 2; innovationDelta -= 7; coachKey = `coach_r3_ignorearchitects`; break;
                }

                summaryKey = (d.leaders === `resourced` && d.time >= 5 && d.legitimacy === `sponsornoformal` && d.capture === `mentoring`) ? `sum_r3_good` : (ds.mandatedCommunities || d.time <= 2 ? `sum_r3_paper` : `sum_r3_weak`);
            } else if (round === 4) {
                // Commit the architecture & pitch the CEO (Common Error 5 + accountability).
                switch (d.kpis) {
                    case `quarterly`: engagementDelta += 5; innovationDelta += 4; coachKey = `coach_r4_quarterly`; break;
                    case `annual`: engagementDelta += 1; coachKey = `coach_r4_annual`; break;
                    case `promise`: engagementDelta -= 4; paperDelta += 4; coachKey = `coach_r4_promise`; break;
                }

                // Sustainment once launch energy fades.
                switch (d.sustain) {
                    case `embed`: engagementDelta += 8; innovationDelta += 3; break;
                    case `relaunch`: engagementDelta += 2; coachKey = (coachKey === `coach_r4_quarterly`) ? coachKey : `coach_r4_relaunch`; break;
                    case `launchenergy`: engagementDelta -= 10; paperDelta += 4; coachKey = `coach_r4_launchenergy`; break;
                }

                // The CEO pitch — causal chain vs coercion vs vagueness.
                switch (d.pitch) {
                    case `causalchain`: engagementDelta += 5; innovationDelta += 3; coachKey = (d.kpis === `quarterly` && d.sustain === `embed`) ? `coach_r4_causalchain` : coachKey; break;
                    case `coerce`: engagementDelta -= 10; paperDelta += 14; coachKey = `coach_r4_coerce`; break;
                    case `vague`: engagementDelta -= 6; coachKey = (coachKey === `coach_default`) ? `coach_r4_vague` : coachKey; break;
                }

                // Conviction nudges engagement.
                engagementDelta += Math.round((d.conviction - 60) / 8);

                summaryKey = (d.kpis === `quarterly` && d.sustain === `embed` && d.pitch === `causalchain`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Resource accounting.
            ds.budgetUsed = Math.round(ds.budgetUsed + spend);
            ds.timeUsed = Math.round((ds.timeUsed + time) * 10) / 10;
            if (ds.budgetUsed > this.BUDGET_CAP) ds.overBudget = true;

            // Engagement (genuine, voluntary participation) and innovation move on their deltas.
            ds.engagement = Math.max(0, Math.min(100, ds.engagement + engagementDelta));
            ds.innovation = Math.max(0, Math.min(100, ds.innovation + innovationDelta));

            // Knowledge-sharing / reuse rate is driven by genuine engagement PLUS coerced paper gains.
            // Paper gains lift the headline number but not real engagement — and signal fragility.
            const engagementGain = Math.max(0, engagementDelta) * 0.82;
            const paperGain = paperDelta * 0.85;
            const sharingDelta = engagementGain + paperGain + Math.min(0, engagementDelta) * 0.35;
            ds.sharing = Math.max(0, Math.min(100, ds.sharing + sharingDelta));

            // Value recovered: only GENUINE reuse recovers the EUR 11M waste, so it tracks the
            // share of sharing that is backed by real engagement, not paper compliance.
            const realShare = Math.max(0, Math.min(1, ds.engagement / 100));
            ds.recovered = Math.round(this.WASTE_TOTAL * (ds.sharing / 100) * (0.45 + 0.55 * realShare) * 10) / 10;

            ds.sharingHistory.push(Math.round(ds.sharing));
            ds.engagementHistory.push(Math.round(ds.engagement));
            ds.innovationHistory.push(Math.round(ds.innovation));

            if (round === this.ROUNDS.length && ds.sharing < this.TARGET_SHARING) ds.targetMissed = true;

            // Persist the composite every period so the grading/reporting layer can read it
            // (express/results_utils.php::express_resolveDomainScore reads domainState.performance.overallScore).
            ds.performance = { overallScore: this._composite(ds) };

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                sharing: Math.round(ds.sharing),
                sharingDelta: Math.round(sharingDelta),
                engagement: Math.round(ds.engagement),
                engagementDelta: Math.round(engagementDelta),
                innovation: Math.round(ds.innovation),
                innovationDelta: Math.round(innovationDelta),
                recovered: ds.recovered,
                budgetUsed: ds.budgetUsed,
                timeUsed: ds.timeUsed,
                repositoryReflex: ds.repositoryReflex,
                mandatedCommunities: ds.mandatedCommunities,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _composite(ds) {
            const sharing = Math.min(100, Math.round(ds.sharing));
            const engagement = Math.round(ds.engagement);
            const innovation = Math.round(ds.innovation);
            return Math.round(sharing * 0.35 + engagement * 0.35 + innovation * 0.30);
        }

        _cl(key, fallback) {
            try {
                const v = (window.mySimulation && typeof window.mySimulation.t === `function`)
                    ? window.mySimulation.t(key) : key;
                return (v && v !== key) ? v : fallback;
            } catch (e) { return fallback; }
        }

        _money(thousands) {
            // Locale-aware EUR formatter. EN: symbol before (€1.2M / €600K).
            // ES: symbol after, comma decimal (1,2 M€ / 600 K€).
            const es = (window.mySimulation && window.mySimulation.language === `es`);
            const k = Math.round(Number(thousands));
            if (k >= 1000) {
                const millions = k / 1000;
                const txt = (Math.round(millions * 10) / 10).toFixed(1);
                if (es) return txt.replace(`.`, `,`) + ` M€`;
                return `€` + txt + `M`;
            }
            if (es) return k + ` K€`;
            return `€` + k + `K`;
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);
            uiManager.bind(`sharingDisplay`, `domainState.sharing`, (v) => {
                const card = document.querySelector(`.communitysim-card-sharing`);
                if (card) {
                    card.classList.toggle(`communitysim-sharing-target`, Number(v) >= this.TARGET_SHARING);
                    card.classList.toggle(`communitysim-sharing-fail`, Number(v) < this.TARGET_SHARING);
                }
                return Math.round(Number(v)) + `%`;
            });
            uiManager.bind(`engagementDisplay`, `domainState.engagement`, (v) => Math.round(v));
            uiManager.bind(`innovationDisplay`, `domainState.innovation`, (v) => Math.round(v));
            uiManager.bind(`recoveredDisplay`, `domainState.recovered`, (v) => this._money(Number(v) * 1000));
            uiManager.bind(`budgetDisplay`, `domainState.budgetUsed`, (v) => {
                const block = document.querySelector(`.communitysim-resource-block`);
                if (block) block.classList.toggle(`communitysim-resource-over`, Number(v) > this.BUDGET_CAP + 0.001);
                return this._money(Number(v)) + ` / €1.2M`;
            });
            uiManager.bind(`timeDisplay`, `domainState.timeUsed`, (v) => {
                const es = (window.mySimulation && window.mySimulation.language === `es`);
                const num = Number(v).toFixed(1);
                const shown = es ? num.replace(`.`, `,`) : num;
                return shown + `% / 5%`;
            });

            const self = this;

            // Urgency slider readout.
            const urg = document.getElementById(`urgencyInput`);
            const urgReadout = document.getElementById(`urgencyReadout`);
            if (urg && urgReadout) {
                urgReadout.textContent = urg.value;
                urg.addEventListener(`input`, function() { urgReadout.textContent = urg.value; });
            }

            // Time slider readout (supports decimals; comma decimal in Spanish).
            const tm = document.getElementById(`timeInput`);
            const tmReadout = document.getElementById(`timeReadout`);
            const fmtTime = function(val) {
                const es = (window.mySimulation && window.mySimulation.language === `es`);
                return es ? String(val).replace(`.`, `,`) : String(val);
            };
            if (tm && tmReadout) {
                tmReadout.textContent = fmtTime(tm.value);
                tm.addEventListener(`input`, function() { tmReadout.textContent = fmtTime(tm.value); });
            }

            // Budget allocation live total.
            const allocIds = [`communitiesInput`, `rotationInput`, `directoryInput`, `toolsInput`, `repositoryInput`, `conferenceInput`];
            const spendReadout = document.getElementById(`spendReadout`);
            const recompute = function() {
                let total = 0;
                allocIds.forEach((id) => {
                    const el = document.getElementById(id);
                    if (el) total += (parseFloat(el.value) || 0);
                });
                total = Math.round(total);
                if (spendReadout) spendReadout.textContent = self._money(total);
                const bar = document.querySelector(`.communitysim-alloc-readout`);
                if (bar) bar.style.color = (total > self.BUDGET_CAP) ? `#c0392b` : ``;
            };
            allocIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recompute);
            });
            recompute();
        }

