        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.sharingHistory.map((_, i) => (i === 0 ? `Start` : `R` + i));
            return {
                communityChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.sharingHistory },
