        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const sharing = Math.round(ds.sharing);
            const engagement = Math.round(ds.engagement);
            const innovation = Math.round(ds.innovation);
            const recovered = ds.recovered;

            const hitTarget = sharing >= this.TARGET_SHARING;
            const realFlow = engagement >= 55 && innovation >= 45;
            const paper = ds.repositoryReflex || ds.mandatedCommunities || (hitTarget && engagement < 40);
            const composite = this._composite(ds);

            let performanceKey = `grade_stuck`;
            if (hitTarget && realFlow && composite >= 70) performanceKey = `grade_cultivated`;
            else if (hitTarget && realFlow) performanceKey = `grade_credible`;
            else if (hitTarget && paper) performanceKey = `grade_paper`;
            else if (hitTarget) performanceKey = `grade_thin`;
            else if (sharing > this.START_SHARING + 18) performanceKey = `grade_short`;
            const performance = window.mySimulation.t(performanceKey);

            const insights = [];
            if (hitTarget && realFlow) insights.push(window.mySimulation.t(`insight_cultivated`));
            else if (hitTarget && paper) insights.push(window.mySimulation.t(`insight_paper`));
            else if (hitTarget) insights.push(window.mySimulation.t(`insight_thin`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (engagement < 40) insights.push(window.mySimulation.t(`insight_lowengagement`));
            if (innovation < 40) insights.push(window.mySimulation.t(`insight_lowinnovation`));
            if (ds.overBudget) insights.push(window.mySimulation.t(`insight_overbudget`));
            if (hitTarget && realFlow && recovered >= 5) insights.push(window.mySimulation.t(`insight_recovered`));

            return {
                sharing: sharing,
                engagement: engagement,
                innovation: innovation,
                recovered: recovered,
                hitTarget: hitTarget,
                paper: paper,
                composite: composite,
                overallScore: composite,
                performanceKey: performanceKey,
                performance: performance,
                sound: (hitTarget && realFlow),
                repositoryReflex: ds.repositoryReflex,
                mandatedCommunities: ds.mandatedCommunities,
                overBudget: ds.overBudget,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const T = (window.mySimulation && typeof window.mySimulation.t === `function`)
                ? function(k) { return window.mySimulation.t(k); }
                : function(k) { return k; };
            const s = summary || {};
            const score = (typeof s.overallScore === `number`) ? s.overallScore
                : (typeof s.composite === `number` ? s.composite : 0);
            const grade = s.performance || (s.performanceKey ? T(s.performanceKey) : ``);
            const metBadge = s.sound
                ? `<span class="communitysim-cm-badge communitysim-cm-yes">` + T(`cm_accelerated`) + `</span>`
                : `<span class="communitysim-cm-badge communitysim-cm-no">` + T(`cm_notaccelerated`) + `</span>`;
            let failBadges = ``;
            if (s.repositoryReflex) failBadges += ` <span class="communitysim-cm-badge communitysim-cm-fail">` + T(`cm_repository`) + `</span>`;
            if (s.mandatedCommunities) failBadges += ` <span class="communitysim-cm-badge communitysim-cm-fail">` + T(`cm_mandated`) + `</span>`;
            if (s.overBudget) failBadges += ` <span class="communitysim-cm-badge communitysim-cm-fail">` + T(`cm_overbudget`) + `</span>`;
            const insights = Array.isArray(s.insights) ? s.insights : [];
            const items = insights.map(function(t) { return `<li>` + t + `</li>`; }).join(``);
            const recovered = this._money(Number(s.recovered || 0) * 1000);
            const metrics = ``
                + `<div class="communitysim-cm-metric"><span class="communitysim-cm-mv">` + Math.round(s.sharing || 0) + `%</span><span class="communitysim-cm-ml">` + T(`cm_m_sharing`) + `</span></div>`
                + `<div class="communitysim-cm-metric"><span class="communitysim-cm-mv">` + Math.round(s.engagement || 0) + `</span><span class="communitysim-cm-ml">` + T(`cm_m_engagement`) + `</span></div>`
                + `<div class="communitysim-cm-metric"><span class="communitysim-cm-mv">` + Math.round(s.innovation || 0) + `</span><span class="communitysim-cm-ml">` + T(`cm_m_innovation`) + `</span></div>`
                + `<div class="communitysim-cm-metric"><span class="communitysim-cm-mv">` + recovered + `</span><span class="communitysim-cm-ml">` + T(`cm_m_recovered`) + `</span></div>`;
            return ``
                + `<div class="communitysim-completion">`
                +   `<div class="communitysim-cm-head">`
                +     `<div class="communitysim-cm-score">` + score + `<span class="communitysim-cm-score-max">/100</span></div>`
                +     `<div class="communitysim-cm-grade">` + grade + ` ` + metBadge + failBadges + `</div>`
                +   `</div>`
                +   `<div class="communitysim-cm-metrics">` + metrics + `</div>`
                +   `<div class="communitysim-cm-insights-title">` + T(`cm_debrief`) + `</div>`
                +   `<ul class="communitysim-cm-insights">` + items + `</ul>`
                + `</div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.repositoryReflex) return window.mySimulation.t(`hint_repository`);
            if (ds.mandatedCommunities) return window.mySimulation.t(`hint_mandate`);
            if (ds.engagement < 30) return window.mySimulation.t(`hint_engagement`);
            if (state.currentPeriod >= 3 && ds.sharing < 40) return window.mySimulation.t(`hint_behind`);
            if (ds.sharing >= this.TARGET_SHARING && ds.engagement >= 55 && ds.innovation >= 45) return window.mySimulation.t(`hint_strong`);
            return null;
        }

